<?php
$ctl=$panel==='control';$panel==='admin'?admin_bootstrap():control_bootstrap();if($ctl?control_user():admin_user()){header('Location: '.url($panel.'/index.php'));exit;}
if(empty($_SESSION['auth_csrf']))$_SESSION['auth_csrf']=bin2hex(random_bytes(24));$error='';$retry=0;$challenge='';$username='';$remember=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['auth_csrf'],(string)($_POST['csrf']??''))){$error='انتهت صلاحية النموذج، أعد المحاولة';http_response_code(403);}else{
 $username=trim((string)($_POST['username']??''));$remember=!empty($_POST['remember']);$challenge=(string)($_POST['challenge']??'');
 try{$r=auth_login_flow($panel,$_POST);if(!empty($r['ok'])){session_regenerate_id(true);header('Location: '.url($panel.'/index.php'));exit;}if(!empty($r['requires_totp']))$challenge=$r['challenge'];else{$error=$r['error']??'تعذر الدخول';$retry=(int)($r['retry_after']??0);http_response_code($r['status']??400);}}catch(Throwable $e){$error='تعذر إكمال تسجيل الدخول، تحقق من إعداد الخادم';http_response_code(503);}
 }}
$storeName=setting('store_name','آي ستور');$logo=setting('intro_logo','');if($logo!==''&&!str_starts_with($logo,'data:')&&!is_file(APP_ROOT.'/'.ltrim($logo,'/')))$logo='';
function login_mark(string $logo,string $name):string{return '<span class="sl-mark">'.($logo!==''?'<img src="'.e(str_starts_with($logo,'data:')?$logo:url($logo)).'" alt="'.e($name).'">':'<svg width="27" height="27" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 9l2-6h14l2 6v3a3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-6 0V9zM5 15v6h14v-6M9 21v-5h6v5"/></svg>').'</span>';}
?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>دخول <?=e($storeName)?></title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet"><link href="<?=e(url('assets/secure-login.css'))?>" rel="stylesheet"></head><body><main class="secure-login"><aside><div class="sl-brand"><?=login_mark($logo,$storeName)?><?=e($storeName)?></div><div class="sl-eyebrow">I STORE · LIBYA</div><h1><?=$ctl?'هوية متجرك،<br>بين يديك.':'كل تفاصيل متجرك،<br>في مكان واحد.'?></h1><p><?=$ctl?'خصص هوية المتجر والمحتوى والتكاملات من لوحة مستقلة.':'إدارة الطلبات والمنتجات والعملاء، بواجهة بسيطة وتجربة دخول أكثر أمانا.'?></p><small>مساحة خاصة بفريق إدارة المتجر</small></aside><section class="sl-pane"><div class="sl-card"><div class="sl-mobilebrand"><?=login_mark($logo,$storeName)?><?=e($storeName)?></div><span class="sl-tag"><?=$ctl?'لوحة الكنترول · إعدادات الموقع':'لوحة التحكم · إدارة المتجر'?></span><?php if($challenge):?><div class="sl-shield">♢</div><h2>تحقق من هويتك</h2><p class="sl-desc">أدخل الرمز المكون من 6 أرقام من تطبيق المصادقة لإكمال تسجيل الدخول. يمكنك استخدام رمز استرداد بدلا منه.</p><?php else:?><h2>مرحبا بعودتك</h2><p class="sl-desc">سجل الدخول <?=$ctl?'لإدارة إعدادات الموقع':'إلى لوحة إدارة متجرك'?>.</p><?php endif;?>
<form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['auth_csrf'])?>"><?php if($error):?><div role="alert" class="sl-alert"><?=e($error)?><?php if($retry):?><br>حاول مجددا بعد:<strong class="sl-timer" dir="ltr" id="timer" data-seconds="<?=$retry?>"><?=intdiv($retry,60)?>:<?=str_pad((string)($retry%60),2,'0',STR_PAD_LEFT)?></strong><?php endif;?></div><?php endif;?>
<?php if($challenge):?><input type="hidden" name="challenge" value="<?=e($challenge)?>"><label class="sl-field" for="code">رمز التحقق أو الاسترداد</label><div class="sl-input"><input id="code" name="code" dir="ltr" autocomplete="one-time-code" required autofocus placeholder="000000"></div><p class="sl-help">الرمز يتغير كل 30 ثانية. تحقق من ضبط وقت جهازك تلقائيا.</p>
<?php else:?><label class="sl-field" for="username">اسم المستخدم</label><div class="sl-input"><input id="username" name="username" autocomplete="username" dir="ltr" value="<?=e($username)?>" required autofocus placeholder="اسم المستخدم"></div><label class="sl-field" for="password">كلمة المرور</label><div class="sl-input"><input id="password" name="password" type="password" autocomplete="current-password" dir="ltr" required placeholder="أدخل كلمة المرور"><button type="button" class="sl-eye" aria-label="إظهار كلمة المرور" onclick="const p=document.getElementById('password');p.type=p.type==='password'?'text':'password';this.textContent=p.type==='password'?'إظهار':'إخفاء';this.setAttribute('aria-label',p.type==='password'?'إظهار كلمة المرور':'إخفاء كلمة المرور')">إظهار</button></div><label class="sl-remember"><input type="checkbox" name="remember" value="1" <?=$remember?'checked':''?>>تذكرني على هذا الجهاز</label><p class="sl-help">بدون «تذكرني»، لا نحفظ دخولا دائما على الجهاز.<br>استعادة المتصفح قد تبقي الجلسة، ويكملها حد الخمول.</p><?php endif;?><button class="sl-primary" id="submit" <?=$retry?'disabled':''?>><?=$retry?'يرجى الانتظار':($challenge?'تحقق وادخل':'تسجيل الدخول ←')?></button></form><?php if($challenge):?><a class="sl-back" href="<?=e(url($panel.'/login.php'))?>">العودة إلى تسجيل الدخول</a><?php endif;?><div class="sl-security">♢ دخول مخصص للمشرفين المصرح لهم فقط</div><?php if(!$challenge):?><a class="sl-back" href="<?=e(url())?>">العودة إلى المتجر</a><?php endif;?></div></section></main><script>const t=document.getElementById('timer');if(t){let n=Number(t.dataset.seconds);setInterval(()=>{n=Math.max(0,n-1);t.textContent=Math.floor(n/60)+':'+String(n%60).padStart(2,'0');if(n===0){document.getElementById('submit').disabled=false;document.getElementById('submit').textContent='تسجيل الدخول';}},1000);}</script></body></html>
